rep("  const chMutK = () => 1 + 0.02 * chTrait('mut');", "  const chMutK = () => 1 + 0.01 * chTrait('mut');   /* c594: 20단계 */")
rep("  const chStrB = () => 0.15 * chTrait('str');", "  const chStrB = () => 0.075 * chTrait('str');   /* c594 */")
