rep("fx: (L) => `유혹 저항력 -${(0.2 * L).toFixed(1)} · 군인 ${Math.round((10 - (8 - 0.2 * L)) * 10)}% · 경찰 ${Math.round((10 - (5 - 0.2 * L)) * 10)}%` }",
    "fx: (L) => `유혹 저항력 -${(0.1 * L).toFixed(1)} · 군인 ${Math.round((10 - (8 - 0.1 * L)) * 10)}% · 경찰 ${Math.round((10 - (5 - 0.1 * L)) * 10)}%` }")
