rep("bomb: ['', (n) => `${+(1.7 + 0.5 * Math.min(5, n) + 0.17 * chTrait('bomb')).toFixed(1)}칸·", "bomb: ['', (n) => `${+(1.7 + 0.5 * Math.min(5, n) + 0.085 * chTrait('bomb')).toFixed(1)}칸·")
